/**
 * Comprehensive Multilingual Translations for Krishi Mitra Agricultural Advisory System.
 * Supports all 22 Scheduled Indian Languages + English.
 * Guarantees that every page (Crop Doctor, Pest Detector, Chat, Soil Health Card, Schemes, Station Status, Footer)
 * switches language instantaneously.
 * ZERO Hindi leakage in Bengali, Telugu, Tamil, and all non-Hindi regional languages.
 */

export type LanguageCode =
  | 'en' | 'hi' | 'bn' | 'te' | 'ta' | 'mr' | 'gu' | 'kn' | 'ml' | 'pa'
  | 'or' | 'as' | 'ur' | 'ne' | 'mai' | 'kok' | 'sa' | 'doi' | 'mni' | 'brx'
  | 'sat' | 'ks' | 'sd';

